macro_rules! deps {
    () => {
        TransitState!();
        TransitProcessResult!();
        DirOptions!();
        Result!();
        ErrorKind!();
        CopyOptions!();
        TransitProcess!();
    };
}

macro_rules! copy_with_progress {
    () => {
        deps!();
        # [doc = " Copies the directory contents from one place to another using recursive method,"] # [doc = " with information about progress. This function will also copy the"] # [doc = " permission bits of the original files to destination files (not for directories)."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This function will return an error in the following situations, but is not limited to just"] # [doc = " these cases:"] # [doc = ""] # [doc = " * This `from` path is not a directory."] # [doc = " * This `from` directory does not exist."] # [doc = " * Invalid folder name for `from` or `to`."] # [doc = " * The current process does not have the permission to access `from` or write `to`."] # [doc = ""] # [doc = " # Example"] # [doc = " ```rust,ignore"] # [doc = " extern crate fs_extra;"] # [doc = " use fs_extra::dir::copy;"] # [doc = ""] # [doc = " let options = CopyOptions::new(); //Initialize default values for CopyOptions"] # [doc = " let handle = |process_info: TransitProcess|  {"] # [doc = "     println!(\"{}\", process_info.total_bytes);"] # [doc = "     fs_extra::dir::TransitProcessResult::ContinueOrAbort"] # [doc = " }"] # [doc = " // copy source/dir1 to target/dir1"] # [doc = " copy_with_progress(\"source/dir1\", \"target/dir1\", &options, handle)?;"] # [doc = ""] # [doc = " ```"] pub fn copy_with_progress < P , Q , F > (from : P , to : Q , options : & CopyOptions , mut progress_handler : F ,) -> Result < u64 > where P : AsRef < Path > , Q : AsRef < Path > , F : FnMut (TransitProcess) -> TransitProcessResult , { let from = from . as_ref () ; if ! from . exists () { if let Some (msg) = from . to_str () { let msg = format ! ("Path \"{}\" does not exist or you don't have access!" , msg) ; err ! (& msg , ErrorKind :: NotFound) ; } err ! ("Path does not exist or you don't have access!" , ErrorKind :: NotFound) ; } let mut to : PathBuf = to . as_ref () . to_path_buf () ; if ! from . is_dir () { if let Some (msg) = from . to_str () { let msg = format ! ("Path \"{}\" is not a directory!" , msg) ; err ! (& msg , ErrorKind :: InvalidFolder) ; } err ! ("Path is not a directory!" , ErrorKind :: InvalidFolder) ; } let dir_name ; if let Some (val) = from . components () . last () { dir_name = val . as_os_str () ; } else { err ! ("Invalid folder from" , ErrorKind :: InvalidFolder) ; } if (to . exists () || ! options . copy_inside) && ! options . content_only { to . push (dir_name) ; } let mut read_options = DirOptions :: new () ; if options . depth > 0 { read_options . depth = options . depth ; } let dir_content = get_dir_content2 (from , & read_options) ? ; for directory in dir_content . directories { let tmp_to = Path :: new (& directory) . strip_prefix (from) ? ; let dir = to . join (& tmp_to) ; if ! dir . exists () { if options . copy_inside { create_all (dir , false) ? ; } else { create (dir , false) ? ; } } } let mut result : u64 = 0 ; let mut info_process = TransitProcess { copied_bytes : 0 , total_bytes : dir_content . dir_size , file_bytes_copied : 0 , file_total_bytes : 0 , file_name : String :: new () , state : TransitState :: Normal , } ; let mut options = options . clone () ; for file in dir_content . files { let mut to = to . to_path_buf () ; let tp = Path :: new (& file) . strip_prefix (from) ? ; let path = to . join (& tp) ; let file_name = path . file_name () ; if file_name . is_none () { err ! ("No file name") ; } let file_name = file_name . unwrap () ; to . push (file_name) ; let mut file_options = super :: file :: CopyOptions { overwrite : options . overwrite , skip_exist : options . skip_exist , buffer_size : options . buffer_size , } ; if let Some (file_name) = file_name . to_str () { info_process . file_name = file_name . to_string () ; } else { err ! ("Invalid file name" , ErrorKind :: InvalidFileName) ; } info_process . file_bytes_copied = 0 ; info_process . file_total_bytes = Path :: new (& file) . metadata () ? . len () ; let mut result_copy : Result < u64 > ; let mut work = true ; let copied_bytes = result ; while work { { let _progress_handler = | info : super :: file :: TransitProcess | { info_process . copied_bytes = copied_bytes + info . copied_bytes ; info_process . file_bytes_copied = info . copied_bytes ; progress_handler (info_process . clone ()) ; } ; result_copy = super :: file :: copy_with_progress (& file , & path , & file_options , _progress_handler) ; } match result_copy { Ok (val) => { result += val ; work = false ; } Err (err) => match err . kind { ErrorKind :: AlreadyExists => { let mut info_process = info_process . clone () ; info_process . state = TransitState :: Exists ; let user_decide = progress_handler (info_process) ; match user_decide { TransitProcessResult :: Overwrite => { file_options . overwrite = true ; } TransitProcessResult :: OverwriteAll => { file_options . overwrite = true ; options . overwrite = true ; } TransitProcessResult :: Skip => { file_options . skip_exist = true ; } TransitProcessResult :: SkipAll => { file_options . skip_exist = true ; options . skip_exist = true ; } TransitProcessResult :: Retry => { } TransitProcessResult :: ContinueOrAbort => { let err_msg = err . to_string () ; err ! (err_msg . as_str () , err . kind) } TransitProcessResult :: Abort => { let err_msg = err . to_string () ; err ! (err_msg . as_str () , err . kind) } } } ErrorKind :: PermissionDenied => { let mut info_process = info_process . clone () ; info_process . state = TransitState :: Exists ; let user_decide = progress_handler (info_process) ; match user_decide { TransitProcessResult :: Overwrite => { err ! ("Overwrite denied for this situation!" , ErrorKind :: Other) ; } TransitProcessResult :: OverwriteAll => { err ! ("Overwrite denied for this situation!" , ErrorKind :: Other) ; } TransitProcessResult :: Skip => { file_options . skip_exist = true ; } TransitProcessResult :: SkipAll => { file_options . skip_exist = true ; options . skip_exist = true ; } TransitProcessResult :: Retry => { } TransitProcessResult :: ContinueOrAbort => { let err_msg = err . to_string () ; err ! (err_msg . as_str () , err . kind) } TransitProcessResult :: Abort => { let err_msg = err . to_string () ; err ! (err_msg . as_str () , err . kind) } } } _ => { let err_msg = err . to_string () ; err ! (err_msg . as_str () , err . kind) } } , } } } Ok (result) }
    };
}

copy_with_progress!();